final class AcroControl {
    private static final double RATE = Math.toRadians(60);

    public static int[] control(Vec3 p, Vec3 v, Vec3 f0, Vec3 u0, Vec3 c, Vec3 n, double cruise, double gain, double lead, double tiltDeg) {
        Vec3 f = f0.norm();
        Vec3 u = u0.sub(f.mul(u0.dot(f))).norm();
        double along = p.sub(c).dot(n);
        Vec3 lat = p.sub(c).sub(n.mul(along));
        double latLen = lat.len();
        boolean cone = along < 0 && latLen < -along * 1.2 + 300;
        Vec3 aim = cone ? c.add(n.mul(along * lead + 200))
                : c.add(n.mul(-Math.max(1200, latLen))).add(lat.norm().mul(Math.min(latLen, 700)));
        double dist = aim.sub(p).len();
        double speed = cone ? cruise : Math.min(cruise, Math.sqrt(2 * 30 * dist) + 60);
        Vec3 dir = aim.sub(p).norm();
        Vec3 vd = dir.mul(speed);
        double floorV = -(p.z() - 350) * 0.25;
        if (vd.z() < floorV) vd = new Vec3(vd.x(), vd.y(), floorV);
        Vec3 a = vd.sub(v).mul(gain);
        double az = Math.max(1, a.z() + 20);
        double h = Math.hypot(a.x(), a.y());
        double limit = az * Math.tan(Math.toRadians(tiltDeg));
        double ax = a.x(), ay = a.y();
        if (h > limit) { ax *= limit / h; ay *= limit / h; }
        Vec3 acc = new Vec3(ax, ay, az);
        Vec3 ut = acc.norm();
        Vec3 heading = new Vec3(dir.x(), dir.y(), 0);
        if (heading.len() < 1e-6) heading = new Vec3(f.x(), f.y(), 0);
        Vec3 ft = heading.sub(ut.mul(heading.dot(ut)));
        if (ft.len() < 1e-6) ft = f.sub(ut.mul(f.dot(ut)));
        ft = ft.norm();
        Vec3 w = rotation(f, u, ft, ut);
        Vec3 r = f.cross(u);
        int pitch = clamp((int) Math.round(-w.dot(r) / RATE * 100));
        int roll = clamp((int) Math.round(w.dot(f) / RATE * 100));
        int yaw = clamp((int) Math.round(-w.dot(u) / RATE * 100));
        double tiltErr = Math.acos(Math.max(-1, Math.min(1, u.dot(ut))));
        double thrust = acc.len() * Math.max(0, Math.cos(tiltErr));
        int throttle = Math.max(0, Math.min(100, (int) Math.round(thrust / 50 * 100)));
        return new int[]{throttle, yaw, pitch, roll};
    }

    private static int clamp(int x) { return Math.max(-100, Math.min(100, x)); }

    static Vec3 rotation(Vec3 f, Vec3 u, Vec3 ft, Vec3 ut) {
        double[] qc = quat(f, u), qt = quat(ft, ut);
        double w = qt[0] * qc[0] + qt[1] * qc[1] + qt[2] * qc[2] + qt[3] * qc[3];
        double x = -qt[0] * qc[1] + qt[1] * qc[0] - qt[2] * qc[3] + qt[3] * qc[2];
        double y = -qt[0] * qc[2] + qt[1] * qc[3] + qt[2] * qc[0] - qt[3] * qc[1];
        double z = -qt[0] * qc[3] - qt[1] * qc[2] + qt[2] * qc[1] + qt[3] * qc[0];
        if (w < 0) { w = -w; x = -x; y = -y; z = -z; }
        double s = Math.sqrt(x * x + y * y + z * z);
        if (s == 0) return Vec3.ZERO;
        double angle = 2 * Math.atan2(s, w);
        return new Vec3(x, y, z).mul(angle / s);
    }

    static double[] quat(Vec3 f, Vec3 u) {
        Vec3 l = u.cross(f);
        double m00 = f.x(), m01 = l.x(), m02 = u.x(), m10 = f.y(), m11 = l.y(), m12 = u.y(), m20 = f.z(), m21 = l.z(), m22 = u.z();
        double tr = m00 + m11 + m22, s;
        if (tr > 0) {
            s = Math.sqrt(tr + 1) * 2;
            return new double[]{s / 4, (m21 - m12) / s, (m02 - m20) / s, (m10 - m01) / s};
        } else if (m00 > m11 && m00 > m22) {
            s = Math.sqrt(1 + m00 - m11 - m22) * 2;
            return new double[]{(m21 - m12) / s, s / 4, (m01 + m10) / s, (m02 + m20) / s};
        } else if (m11 > m22) {
            s = Math.sqrt(1 + m11 - m00 - m22) * 2;
            return new double[]{(m02 - m20) / s, (m01 + m10) / s, s / 4, (m12 + m21) / s};
        } else {
            s = Math.sqrt(1 + m22 - m00 - m11) * 2;
            return new double[]{(m10 - m01) / s, (m02 + m20) / s, (m12 + m21) / s, s / 4};
        }
    }
}

