record Vec3(double x, double y, double z) {
    public static final Vec3 ZERO = new Vec3(0, 0, 0);
    public static final Vec3 UP = new Vec3(0, 0, 1);

    public Vec3 add(Vec3 o) { return new Vec3(x + o.x, y + o.y, z + o.z); }
    public Vec3 sub(Vec3 o) { return new Vec3(x - o.x, y - o.y, z - o.z); }
    public Vec3 mul(double k) { return new Vec3(x * k, y * k, z * k); }
    public double dot(Vec3 o) { return x * o.x + y * o.y + z * o.z; }
    public Vec3 cross(Vec3 o) { return new Vec3(y * o.z - z * o.y, z * o.x - x * o.z, x * o.y - y * o.x); }
    public double len() { return Math.sqrt(dot(this)); }
    public Vec3 norm() { double l = len(); return l == 0 ? this : mul(1 / l); }

    public Vec3 rot(Vec3 k, double a) {
        double c = Math.cos(a), s = Math.sin(a);
        return mul(c).add(k.cross(this).mul(s)).add(k.mul(k.dot(this) * (1 - c)));
    }

    public Vec3 round(double scale) { return new Vec3(r(x, scale), r(y, scale), r(z, scale)); }

    public static double r(double v, double scale) { return Math.floor(v * scale + 0.5) / scale; }
}

final class Rng {
    private long s;

    public Rng(long seed) { s = seed; }

    public long next() {
        long z = (s += 0x9E3779B97F4A7C15L);
        z = (z ^ (z >>> 30)) * 0xBF58476D1CE4E5B9L;
        z = (z ^ (z >>> 27)) * 0x94D049BB133111EBL;
        return z ^ (z >>> 31);
    }

    public int nextInt(int n) { return (int) Long.remainderUnsigned(next(), n); }

    public double nextDouble() { return (next() >>> 11) * 0x1.0p-53; }

    public double range(double a, double b) { return a + (b - a) * nextDouble(); }
}

record Rules(int league, int maxPlayers, int collisions, int boosts, boolean acro, boolean cells, boolean draft) {
    public static final double G = 20, THRUST = 50, DRAG = 0.97, BOOST = 300, RADIUS = 200;
    public static final double GATE_R = 500, GATE_RIM = 600, CUTOUT_SPEED = 250, LAND_SPEED = 150;
    public static final double X = 12000, Y = 12000, Z = 5000;
    public static final double MAX_TILT = Math.toRadians(60), ANGLE_YAW = Math.toRadians(30);
    public static final double SLEW = Math.toRadians(30), ACRO_RATE = Math.toRadians(60);
    public static final int BOOST_RECHARGE = 40, CUTOUT_TURNS = 8, BATTERY = 100, MAX_TURNS = 600, LAPS = 3;
    public static final int NONE = 0, BOUNCE = 1, CUTOUT = 2;
    public static final int CHARGE = 0, SHIELD = 1, GHOST = 2;
    public static final double CLEAR_R = GATE_R - RADIUS, RESTART_HEIGHT = 300, START_SPACING = 450;
    public static final double CELL_PICK = 350, DRAFT_DRAG = 0.9725, DRAFT_LEN = 1500, DRAFT_W = 300;
    public static final int CELL_RESPAWN = 60, SHIELD_TURNS = 30, GHOST_TURNS = 30, START_GHOST = 30, CAM_DEFAULT = 30;

    public static double WOOD_GATE_R = 800, WOOD_MARGIN = 3000, WOOD_SPACING = 2500;

    public double gateR() { return league <= 2 ? WOOD_GATE_R : GATE_R; }

    public double clearR() { return gateR() - RADIUS; }

    public double margin() { return league <= 2 ? WOOD_MARGIN : 1500; }

    public double spacing() { return league <= 2 ? WOOD_SPACING : 3000; }

    public static Rules forLeague(int league) {
        return switch (league) {
            case 1 -> new Rules(1, 2, NONE, 0, false, false, true);
            case 2 -> new Rules(2, 4, BOUNCE, 0, false, false, true);
            case 3 -> new Rules(3, 4, CUTOUT, 1, true, false, true);
            case 4 -> new Rules(4, 4, CUTOUT, 1, true, true, true);
            case 5 -> new Rules(5, 4, CUTOUT, 2, true, true, true);
            default -> new Rules(6, 4, CUTOUT, 3, true, true, true);
        };
    }
}

final class Track {
    public final Vec3[] c;
    public final Vec3[] n;

    public Track(Vec3[] c, Vec3[] n) { this.c = c; this.n = n; }

    public int size() { return c.length; }

    public static Track generate(Rng r, boolean elements) { return generate(r, elements, 1500, 3000); }

    public static Track generate(Rng r, boolean elements, double margin, double spacing) {
        int count = (elements ? 3 : 4) + r.nextInt(3);
        Vec3[] c = new Vec3[count];
        outer:
        for (int i = 0; i < count; ) {
            Vec3 p = new Vec3(Vec3.r(r.range(margin, Rules.X - margin), 1), Vec3.r(r.range(margin, Rules.Y - margin), 1),
                    Vec3.r(r.range(600, 3500), 1));
            for (int j = 0; j < i; j++) if (p.sub(c[j]).len() < spacing) continue outer;
            if (i == 1 && Math.hypot(p.x() - c[0].x(), p.y() - c[0].y()) > 4000) continue;
            c[i++] = p;
        }
        Vec3[] n = new Vec3[count];
        double maxE = Math.toRadians(20);
        for (int i = 0; i < count; i++) {
            Vec3 prev = c[(i - 1 + count) % count], next = c[(i + 1) % count];
            Vec3 d = c[i].sub(prev).norm().add(next.sub(c[i]).norm());
            if (d.len() < 1e-9) d = c[i].sub(prev);
            double h = Math.atan2(d.y(), d.x()) + Math.toRadians(r.range(-35, 35));
            double e = Math.max(-maxE, Math.min(maxE, Math.atan2(d.z(), Math.hypot(d.x(), d.y()))));
            e = Math.max(-maxE, Math.min(maxE, e + Math.toRadians(r.range(-10, 10))));
            n[i] = new Vec3(Math.cos(e) * Math.cos(h), Math.cos(e) * Math.sin(h), Math.sin(e)).round(1e6);
        }
        if (!elements) return new Track(c, n);
        java.util.List<Vec3> oc = new java.util.ArrayList<>(), on = new java.util.ArrayList<>();
        int placed = 0;
        for (int i = 0; i < count; i++) {
            boolean tryIt = i >= 2 && placed < 2 && r.nextDouble() < 0.5;
            int kind = r.nextInt(2);
            boolean flip = r.nextInt(2) == 1;
            Vec3[] el = tryIt ? element(c, i, n[i], kind, flip) : null;
            if (el == null) {
                oc.add(c[i]);
                on.add(n[i]);
            } else {
                placed++;
                oc.add(el[0]);
                on.add(el[1]);
                oc.add(el[2]);
                on.add(el[3]);
            }
        }
        return new Track(oc.toArray(new Vec3[0]), on.toArray(new Vec3[0]));
    }

    private static Vec3[] element(Vec3[] c, int i, Vec3 n, int kind, boolean flip) {
        Vec3 e = new Vec3(n.x(), n.y(), 0).norm().round(1e6);
        Vec3 back = e.mul(-1);
        Vec3 a, b;
        if (kind == 0) {
            double z0 = Math.max(700, Math.min(2400, c[i].z()));
            Vec3 lo = new Vec3(c[i].x(), c[i].y(), z0), hi = new Vec3(c[i].x(), c[i].y(), z0 + 1400);
            a = flip ? hi : lo;
            b = flip ? lo : hi;
        } else {
            Vec3 side = new Vec3(-e.y(), e.x(), 0).mul(flip ? -900 : 900);
            a = c[i].sub(side).round(1);
            b = c[i].add(side).round(1);
        }
        for (Vec3 p : new Vec3[]{a, b}) {
            if (p.x() < 1000 || p.x() > Rules.X - 1000 || p.y() < 1000 || p.y() > Rules.Y - 1000 || p.z() < 600 || p.z() > 4000)
                return null;
            for (int j = 0; j < c.length; j++) if (j != i && p.sub(c[j]).len() < 2000) return null;
        }
        return new Vec3[]{a, e, b, back};
    }
}

record Command(int mode, int throttle, int yaw, int pitch, int roll, boolean boost, boolean use, int cam, String message) {
    public Command(int mode, int throttle, int yaw, int pitch, int roll, boolean boost, String message) {
        this(mode, throttle, yaw, pitch, roll, boost, false, -1, message);
    }

    public static final int ANGLE = 1, ACRO = 2;

    public static Command parse(String line, int mode, Rules rules) {
        String[] t = line.trim().split("\\s+");
        int i = 0;
        if (mode == 0) {
            if (t[0].equals("ANGLE")) mode = ANGLE;
            else if (t[0].equals("ACRO") && rules.acro()) mode = ACRO;
            else throw new IllegalArgumentException("first output must start with ANGLE" + (rules.acro() ? " or ACRO" : ""));
            i = 1;
        } else if (t.length > 0 && (t[0].equals("ANGLE") || t[0].equals("ACRO"))) i = 1;
        if (t.length < i + 4) throw new IllegalArgumentException("expected THROTTLE YAW PITCH ROLL");
        int th = clampInt(t[i], 0, 100), y = clampInt(t[i + 1], -100, 100), p = clampInt(t[i + 2], -100, 100),
                ro = clampInt(t[i + 3], -100, 100);
        i += 4;
        boolean boost = false, use = false;
        int cam = -1;
        while (i < t.length) {
            if (!boost && t[i].equals("BOOST")) { boost = true; i++; }
            else if (!use && t[i].equals("USE")) { use = true; i++; }
            else if (cam < 0 && t[i].equals("CAM") && i + 1 < t.length && t[i + 1].matches("-?\\d+")) { cam = clampInt(t[i + 1], 0, 60); i += 2; }
            else break;
        }
        StringBuilder msg = new StringBuilder();
        for (; i < t.length; i++) msg.append(msg.length() == 0 ? "" : " ").append(t[i]);
        return new Command(mode, th, y, p, ro, boost, use, cam, msg.toString());
    }

    private static int clampInt(String s, int lo, int hi) {
        return Math.max(lo, Math.min(hi, Integer.parseInt(s)));
    }
}

final class Drone {
    public static final int DESTROYED = 0, FLYING = 1, FINISHED = 2;
    public final int id;
    public Vec3 p, v, f, u, w = Vec3.ZERO;
    public int mode, boosts, boostTimer, battery = Rules.BATTERY, cutout, state = FLYING;
    public int nextGate = 1, lap, gatesCleared, endTurn = -1, shield, ghost, item, cam = Rules.CAM_DEFAULT;
    public boolean motorsOff, draft;
    public int lastBoostTurn = -1, lastCellCharge = -1, slot, cutouts;
    public double endDist;

    public Drone(int id, Vec3 p, Vec3 f) { this.id = id; this.p = p; this.v = Vec3.ZERO; this.f = f; this.u = Vec3.UP; }

    public Drone copy(int newId) {
        Drone d = new Drone(newId, p, f);
        d.v = v; d.u = u; d.w = w; d.mode = mode; d.boosts = boosts; d.boostTimer = boostTimer; d.battery = battery;
        d.cutout = cutout; d.state = state; d.nextGate = nextGate; d.lap = lap; d.gatesCleared = gatesCleared;
        d.endTurn = endTurn; d.endDist = endDist; d.shield = shield; d.ghost = ghost; d.item = item; d.cam = cam;
        return d;
    }

    public boolean active() { return state == FLYING; }
}

final class Game {
    public final Rules rules;
    public final Track track;
    public final Drone[] drones;
    public int turn;
    public Vec3[] cellPos = new Vec3[0];
    public int[] cellType = new int[0], cellTimer = new int[0];

    public Game(Rules rules, int players, long seed) {
        this.rules = rules;
        Rng rng = new Rng(seed);
        track = Track.generate(rng, rules.league() >= 3, rules.margin(), rules.spacing());
        int[] slot = new int[players];
        for (int i = 0; i < players; i++) slot[i] = i;
        for (int i = players - 1; i > 0; i--) {
            int j = rng.nextInt(i + 1);
            int t = slot[i]; slot[i] = slot[j]; slot[j] = t;
        }
        Vec3 g0 = track.c[0], g1 = track.c[1];
        double dx = g0.x() - g1.x(), dy = g0.y() - g1.y(), rad = Math.hypot(dx, dy), base = Math.atan2(dy, dx);
        double spacing = Rules.START_SPACING;
        while (spacing > 0 && !startFits(g1, rad, base, players, spacing)) spacing = Math.max(0, spacing - 50);
        drones = new Drone[players];
        for (int i = 0; i < players; i++) {
            double a = base + (slot[i] - (players - 1) / 2.0) * spacing / rad;
            Vec3 p = new Vec3(g1.x() + rad * Math.cos(a), g1.y() + rad * Math.sin(a), Rules.RADIUS).round(100);
            Vec3 f = new Vec3(g1.x() - p.x(), g1.y() - p.y(), 0).norm().round(1e6);
            drones[i] = new Drone(i, p, f);
            drones[i].slot = slot[i];
            drones[i].boosts = rules.boosts();
            if (rules.collisions() != Rules.NONE) drones[i].ghost = Rules.START_GHOST;
        }
        if (rules.cells()) placeCells(rng);
    }

    private void placeCells(Rng rng) {
        int n = track.size();
        int[] legs = new int[n];
        for (int i = 0; i < n; i++) legs[i] = i;
        for (int i = n - 1; i > 0; i--) {
            int j = rng.nextInt(i + 1);
            int t = legs[i]; legs[i] = legs[j]; legs[j] = t;
        }
        List<Vec3> pos = new ArrayList<>();
        for (int k = 0; k < n && pos.size() < 3; k++) {
            Vec3 a = track.c[legs[k]], b = track.c[(legs[k] + 1) % n];
            Vec3 d = new Vec3(b.x() - a.x(), b.y() - a.y(), 0);
            if (d.len() < 2500) continue;
            d = d.norm();
            Vec3 mid = a.add(b).mul(0.5);
            double off = rng.range(800, 1400) * (rng.nextInt(2) == 0 ? 1 : -1);
            double z = mid.z() + rng.range(-300, 300);
            double x = mid.x() - d.y() * off, y = mid.y() + d.x() * off;
            pos.add(new Vec3(Math.max(800, Math.min(Rules.X - 800, x)), Math.max(800, Math.min(Rules.Y - 800, y)),
                    Math.max(500, Math.min(4200, z))).round(1));
        }
        cellPos = pos.toArray(new Vec3[0]);
        cellType = new int[cellPos.length];
        cellTimer = new int[cellPos.length];
        for (int i = 0; i < cellType.length; i++) cellType[i] = i;
    }

    private static boolean startFits(Vec3 g1, double rad, double base, int players, double spacing) {
        for (int k = 0; k < players; k++) {
            double a = base + (k - (players - 1) / 2.0) * spacing / rad;
            double x = g1.x() + rad * Math.cos(a), y = g1.y() + rad * Math.sin(a);
            if (x < 500 || x > Rules.X - 500 || y < 500 || y > Rules.Y - 500) return false;
        }
        return true;
    }

    public Game(Rules rules, Track track, Drone[] drones) {
        this.rules = rules;
        this.track = track;
        this.drones = drones;
    }

    public boolean over() {
        if (turn >= Rules.MAX_TURNS) return true;
        boolean any = false;
        for (Drone d : drones) {
            if (d.state == Drone.FINISHED) return true;
            any |= d.active();
        }
        return !any;
    }

    public void step(Command[] cmds) {
        turn++;
        events.clear();
        for (int i = 0; i < cellTimer.length; i++) if (cellTimer[i] > 0) cellTimer[i]--;
        for (Drone d : drones) {
            if (!d.active()) continue;
            Command c = cmds[d.id];
            if (d.mode == 0) d.mode = c.mode();
            if (c.cam() >= 0) d.cam = c.cam();
            orthonormalize(d);
            if (d.cutout > 0 && d.p.z() - Rules.RADIUS <= Rules.RESTART_HEIGHT) d.cutout = 0;
            d.motorsOff = d.cutout > 0 || d.battery <= 0;
            double thrust = 0;
            if (d.motorsOff) {
                d.w = Vec3.ZERO;
                if (d.cutout > 0) d.cutout--;
            } else {
                if (d.mode == Command.ACRO) acro(d, c);
                else angle(d, c);
                thrust = c.throttle() / 100.0 * Rules.THRUST;
                if (c.use() && d.item != 0) {
                    if (d.item == Rules.SHIELD) d.shield = Rules.SHIELD_TURNS;
                    else d.ghost = Rules.GHOST_TURNS;
                    d.item = 0;
                }
                if (c.boost() && d.boosts > 0) {
                    d.v = d.v.add(d.u.mul(Rules.BOOST));
                    d.lastBoostTurn = turn;
                    if (d.boosts == rules.boosts()) d.boostTimer = Rules.BOOST_RECHARGE;
                    d.boosts--;
                }
            }
            d.v = d.v.add(d.u.mul(thrust)).add(new Vec3(0, 0, -Rules.G));
        }
        int[] cleared = new int[drones.length];
        pickT = new double[cellPos.length];
        java.util.Arrays.fill(pickT, Double.MAX_VALUE);
        pickBy = new boolean[cellPos.length][drones.length];
        move(cleared);
        for (Drone d : drones) d.draft = rules.draft() && d.active() && drafting(d);
        for (Drone d : drones) {
            if (!d.active() && d.endTurn != turn) continue;
            if (d.state == Drone.DESTROYED) continue;
            d.v = d.v.mul(d.draft ? Rules.DRAFT_DRAG : Rules.DRAG).round(100);
            d.p = d.p.round(100);
            d.f = d.f.round(1e6);
            d.u = d.u.round(1e6);
            if (d.boosts < rules.boosts() && --d.boostTimer <= 0) {
                d.boosts++;
                d.boostTimer = d.boosts < rules.boosts() ? Rules.BOOST_RECHARGE : 0;
            }
            d.battery = cleared[d.id] > 0 ? Rules.BATTERY : Math.max(0, d.battery - 1);
            if (d.shield > 0) d.shield--;
            if (d.ghost > 0) d.ghost--;
        }
        for (int k = 0; k < cellPos.length; k++) {
            if (pickT[k] == Double.MAX_VALUE) continue;
            cellTimer[k] = Rules.CELL_RESPAWN;
            for (Drone d : drones) {
                if (!pickBy[k][d.id] || d.state == Drone.DESTROYED) continue;
                if (cellType[k] == Rules.CHARGE) {
                    d.boosts++;
                    d.lastCellCharge = turn;
                    if (d.boosts >= rules.boosts()) d.boostTimer = 0;
                } else d.item = cellType[k];
            }
        }
        if (over()) for (Drone d : drones) if (d.active()) d.endDist = distNext(d);
    }

    private boolean drafting(Drone d) {
        for (Drone o : drones) {
            if (o == d || !o.active()) continue;
            double sp = o.v.len();
            if (sp < 100) continue;
            Vec3 back = o.v.mul(-1 / sp), rel = d.p.sub(o.p);
            double along = rel.dot(back);
            if (along <= 0 || along > Rules.DRAFT_LEN) continue;
            if (rel.sub(back.mul(along)).len() <= Rules.DRAFT_W) return true;
        }
        return false;
    }

    private static void orthonormalize(Drone d) {
        d.f = d.f.norm();
        d.u = d.u.sub(d.f.mul(d.u.dot(d.f))).norm();
    }

    private static void spin(Drone d, Vec3 w) {
        double a = w.len();
        if (a == 0) return;
        Vec3 k = w.mul(1 / a);
        d.f = d.f.rot(k, a);
        d.u = d.u.rot(k, a);
    }

    private static void acro(Drone d, Command c) {
        Vec3 r = d.f.cross(d.u);
        Vec3 w = r.mul(-c.pitch() / 100.0 * Rules.ACRO_RATE)
                .add(d.f.mul(c.roll() / 100.0 * Rules.ACRO_RATE))
                .add(d.u.mul(-c.yaw() / 100.0 * Rules.ACRO_RATE));
        d.w = w;
        spin(d, w);
    }

    private static void angle(Drone d, Command c) {
        Vec3 hf = new Vec3(d.f.x(), d.f.y(), 0);
        if (hf.len() < 1e-6) hf = new Vec3(d.u.x(), d.u.y(), 0).mul(d.f.z() > 0 ? -1 : 1);
        double psi = hf.len() < 1e-6 ? 0 : Math.atan2(hf.y(), hf.x());
        psi -= c.yaw() / 100.0 * Rules.ANGLE_YAW;
        Vec3 f0 = new Vec3(Math.cos(psi), Math.sin(psi), 0), u0 = Vec3.UP, r0 = f0.cross(u0);
        double th = c.pitch() / 100.0 * Rules.MAX_TILT, ph = c.roll() / 100.0 * Rules.MAX_TILT;
        Vec3 f1 = f0.mul(Math.cos(th)).sub(u0.mul(Math.sin(th)));
        Vec3 u1 = u0.mul(Math.cos(th)).add(f0.mul(Math.sin(th)));
        Vec3 u2 = u1.mul(Math.cos(ph)).add(r0.mul(Math.sin(ph)));
        double[] qc = quat(d.f, d.u), qt = quat(f1, u2);
        double w = qt[0] * qc[0] + qt[1] * qc[1] + qt[2] * qc[2] + qt[3] * qc[3];
        double x = -qt[0] * qc[1] + qt[1] * qc[0] - qt[2] * qc[3] + qt[3] * qc[2];
        double y = -qt[0] * qc[2] + qt[1] * qc[3] + qt[2] * qc[0] - qt[3] * qc[1];
        double z = -qt[0] * qc[3] - qt[1] * qc[2] + qt[2] * qc[1] + qt[3] * qc[0];
        if (w < 0) { w = -w; x = -x; y = -y; z = -z; }
        double s = Math.sqrt(x * x + y * y + z * z);
        double a = 2 * Math.atan2(s, w);
        if (a <= Rules.SLEW || s == 0) {
            d.w = s == 0 ? Vec3.ZERO : new Vec3(x, y, z).mul(a / s);
            d.f = f1;
            d.u = u2;
        } else {
            d.w = new Vec3(x, y, z).mul(Rules.SLEW / s);
            spin(d, d.w);
        }
    }

    private static double[] quat(Vec3 f, Vec3 u) {
        Vec3 l = u.cross(f);
        double m00 = f.x(), m01 = l.x(), m02 = u.x(), m10 = f.y(), m11 = l.y(), m12 = u.y(), m20 = f.z(), m21 = l.z(), m22 = u.z();
        double tr = m00 + m11 + m22, s;
        if (tr > 0) {
            s = Math.sqrt(tr + 1) * 2;
            return new double[]{s / 4, (m21 - m12) / s, (m02 - m20) / s, (m10 - m01) / s};
        } else if (m00 > m11 && m00 > m22) {
            s = Math.sqrt(1 + m00 - m11 - m22) * 2;
            return new double[]{(m21 - m12) / s, s / 4, (m01 + m10) / s, (m02 + m20) / s};
        } else if (m11 > m22) {
            s = Math.sqrt(1 + m11 - m00 - m22) * 2;
            return new double[]{(m02 - m20) / s, (m01 + m10) / s, s / 4, (m12 + m21) / s};
        } else {
            s = Math.sqrt(1 + m22 - m00 - m11) * 2;
            return new double[]{(m10 - m01) / s, (m02 + m20) / s, (m12 + m21) / s, s / 4};
        }
    }

    private void move(int[] cleared) {
        double t = 0;
        double R = Rules.RADIUS;
        for (int guard = 0; t < 1 && guard < 64; guard++) {
            double best = 1 - t;
            int type = -1, a = -1, b = -1;
            for (Drone d : drones) {
                if (!d.active()) continue;
                double[] tt = {
                        d.v.z() < 0 ? (d.p.z() - R) / -d.v.z() : 2,
                        d.v.x() < 0 ? (d.p.x() - R) / -d.v.x() : d.v.x() > 0 ? (Rules.X - R - d.p.x()) / d.v.x() : 2,
                        d.v.y() < 0 ? (d.p.y() - R) / -d.v.y() : d.v.y() > 0 ? (Rules.Y - R - d.p.y()) / d.v.y() : 2,
                        d.v.z() > 0 ? (Rules.Z - R - d.p.z()) / d.v.z() : 2};
                for (int k = 0; k < 4; k++) {
                    double x = Math.max(0, tt[k]);
                    if (x < best) { best = x; type = k; a = d.id; }
                }
            }
            if (rules.collisions() != Rules.NONE) {
                for (int i = 0; i < drones.length; i++) {
                    if (!drones[i].active()) continue;
                    if (drones[i].ghost > 0) continue;
                    for (int j = i + 1; j < drones.length; j++) {
                        if (!drones[j].active() || drones[j].ghost > 0) continue;
                        Vec3 dp = drones[j].p.sub(drones[i].p), dv = drones[j].v.sub(drones[i].v);
                        double bq = dp.dot(dv);
                        if (bq >= 0) continue;
                        double aq = dv.dot(dv), cq = dp.dot(dp) - 4 * R * R, x;
                        if (cq <= 0) x = 0;
                        else {
                            double disc = bq * bq - aq * cq;
                            if (disc < 0) continue;
                            x = (-bq - Math.sqrt(disc)) / aq;
                        }
                        if (x < best) { best = x; type = 4; a = i; b = j; }
                    }
                }
            }
            for (Drone d : drones) {
                if (!d.active()) continue;
                Vec3 p0 = d.p;
                d.p = d.p.add(d.v.mul(best));
                gate(d, p0, cleared);
                pick(d, p0, t, best);
            }
            t += best;
            if (type < 0) break;
            if (type == 4) collide(drones[a], drones[b], t);
            else if (type == 0) floor(drones[a]);
            else wall(drones[a], type);
        }
    }

    private void floor(Drone d) {
        d.p = new Vec3(d.p.x(), d.p.y(), Rules.RADIUS);
        if (d.motorsOff || d.cutout > 0 || -d.v.z() > Rules.LAND_SPEED) {
            d.state = Drone.DESTROYED;
            d.endTurn = turn;
            d.endDist = distNext(d);
            d.v = Vec3.ZERO;
        } else d.v = new Vec3(d.v.x(), d.v.y(), 0);
    }

    private static void wall(Drone d, int type) {
        if (type == 1) d.v = new Vec3(-d.v.x(), d.v.y(), d.v.z());
        else if (type == 2) d.v = new Vec3(d.v.x(), -d.v.y(), d.v.z());
        else d.v = new Vec3(d.v.x(), d.v.y(), -d.v.z());
    }

    public final List<double[]> events = new ArrayList<>();

    private void collide(Drone a, Drone b, double at) {
        Vec3 pa = a.p, pb = b.p;
        Vec3 n = b.p.sub(a.p).norm();
        double s = a.v.sub(b.v).dot(n);
        a.v = a.v.sub(n.mul(s));
        b.v = b.v.add(n.mul(s));
        if (rules.collisions() == Rules.CUTOUT && s >= Rules.CUTOUT_SPEED && a.shield == 0 && b.shield == 0) {
            a.cutout = Rules.CUTOUT_TURNS;
            b.cutout = Rules.CUTOUT_TURNS;
            a.cutouts++;
            b.cutouts++;
        }
        events.add(new double[]{a.id, b.id, at, pa.x(), pa.y(), pa.z(), pb.x(), pb.y(), pb.z(), s, a.cutout == Rules.CUTOUT_TURNS && b.cutout == Rules.CUTOUT_TURNS ? 1 : 0});
    }

    private void gate(Drone d, Vec3 p0, int[] cleared) {
        int g = d.nextGate;
        Vec3 c = track.c[g], n = track.n[g];
        double d0 = n.dot(p0.sub(c)), d1 = n.dot(d.p.sub(c));
        if (!(d0 < 0 && d1 >= 0)) return;
        Vec3 x = p0.add(d.p.sub(p0).mul(d0 / (d0 - d1)));
        if (x.sub(c).len() >= rules.clearR()) return;
        cleared[d.id]++;
        d.gatesCleared++;
        d.nextGate = (g + 1) % track.size();
        if (g == 0 && ++d.lap == Rules.LAPS) {
            d.state = Drone.FINISHED;
            d.endTurn = turn;
        }
    }

    private double[] pickT;
    private boolean[][] pickBy;

    private void pick(Drone d, Vec3 p0, double t0, double dt) {
        Vec3 seg = d.p.sub(p0);
        double l2 = seg.dot(seg);
        for (int k = 0; k < cellPos.length; k++) {
            if (cellTimer[k] > 0 || (cellType[k] != Rules.CHARGE && d.item != 0)) continue;
            double s = l2 == 0 ? 0 : Math.max(0, Math.min(1, cellPos[k].sub(p0).dot(seg) / l2));
            if (p0.add(seg.mul(s)).sub(cellPos[k]).len() > Rules.CELL_PICK) continue;
            double at = t0 + s * dt;
            if (at < pickT[k]) {
                pickT[k] = at;
                java.util.Arrays.fill(pickBy[k], false);
            }
            if (at == pickT[k]) pickBy[k][d.id] = true;
        }
    }

    public double distNext(Drone d) { return d.p.sub(track.c[d.nextGate]).len(); }

    public int[] positions() {
        long[] k = new long[drones.length];
        for (Drone d : drones) {
            if (d.state == Drone.FINISHED) k[d.id] = 1_000_000_000_000L - d.endTurn;
            else k[d.id] = d.gatesCleared * 100_000_000L - Math.round(Math.min(d.active() ? distNext(d) : d.endDist, 99_999_999));
        }
        int[] pos = new int[drones.length];
        for (int i = 0; i < k.length; i++) {
            pos[i] = 1;
            for (long x : k) if (x > k[i]) pos[i]++;
        }
        return pos;
    }

    public long[] rankKeys() {
        long[] k = new long[drones.length];
        for (Drone d : drones) {
            if (d.state == Drone.FINISHED) k[d.id] = 1_000_000_000_000L - d.endTurn;
            else k[d.id] = d.gatesCleared * 100_000_000L - Math.round(Math.min(d.endDist, 99_999_999));
        }
        return k;
    }

    public List<String> initLines(int id) {
        List<String> out = new ArrayList<>();
        out.add(drones.length + " " + id + " " + Rules.LAPS + " " + track.size());
        for (int g = 0; g < track.size(); g++) {
            Vec3 c = track.c[g], n = track.n[g];
            out.add(String.format(Locale.ROOT, "%.0f %.0f %.0f %.6f %.6f %.6f %.0f", c.x(), c.y(), c.z(), n.x(), n.y(), n.z(), rules.gateR()));
        }
        out.add(String.valueOf(cellPos.length));
        for (int k = 0; k < cellPos.length; k++)
            out.add(String.format(Locale.ROOT, "%.0f %.0f %.0f %s", cellPos[k].x(), cellPos[k].y(), cellPos[k].z(), new String[]{"CHARGE", "SHIELD", "GHOST"}[cellType[k]]));
        return out;
    }

    public List<String> turnLines() {
        List<String> out = new ArrayList<>();
        for (Drone d : drones) {
            out.add(String.format(Locale.ROOT, "%.2f %.2f %.2f %.2f %.2f %.2f %.6f %.6f %.6f %.6f %.6f %.6f %d %d %d %d %d %d %d %d %d %d",
                    d.p.x(), d.p.y(), d.p.z(), d.v.x(), d.v.y(), d.v.z(), d.f.x(), d.f.y(), d.f.z(), d.u.x(), d.u.y(), d.u.z(),
                    d.nextGate, d.lap, d.boosts, d.boostTimer, d.battery, d.cutout, d.state, d.shield, d.ghost, d.item));
        }
        for (int t : cellTimer) out.add(String.valueOf(t));
        return out;
    }
}

interface Bot {
    void init(List<String> lines);

    String turn(List<String> lines);
}

final class Greedy implements Bot {
    final double cruise, gain, lead, cap;
    int me, gates;
    double[][] gc, gn;
    boolean first = true;

    public Greedy(double cruise, double gain, double lead, double cap) { this.cruise = cruise; this.gain = gain; this.lead = lead; this.cap = cap; }

    public Greedy(double cruise, double gain, double lead) { this(cruise, gain, lead, 1); }

    public Greedy() { this(450, 0.3, 0.5); }

    public void init(List<String> lines) {
        String[] h = lines.get(0).split(" ");
        me = Integer.parseInt(h[1]);
        gates = Integer.parseInt(h[3]);
        gc = new double[gates][];
        gn = new double[gates][];
        for (int g = 0; g < gates; g++) {
            double[] t = nums(lines.get(1 + g));
            gc[g] = new double[]{t[0], t[1], t[2]};
            gn[g] = new double[]{t[3], t[4], t[5]};
        }
    }

    public String turn(List<String> lines) {
        double[] s = nums(lines.get(me));
        int[] k = control(new double[]{s[0], s[1], s[2]}, new double[]{s[3], s[4], s[5]}, new double[]{s[6], s[7], s[8]},
                gc[(int) s[12]], gn[(int) s[12]], cruise, gain, lead);
        k[0] = (int) Math.round(Math.min(k[0], 100 * cap));
        String cmd = k[0] + " " + k[1] + " " + k[2] + " " + k[3];
        if (first) { first = false; return "ANGLE " + cmd; }
        return cmd;
    }

    static int[] control(double[] p, double[] v, double[] f, double[] c, double[] n, double cruise, double gain, double lead) {
        double along = dot(sub(p, c), n);
        double[] lat = sub(sub(p, c), mul(n, along));
        double latLen = len(lat);
        boolean cone = along < 0 && latLen < -along * 1.2 + 300;
        double[] aim = cone ? add(c, mul(n, along * lead + 200))
                : add(add(c, mul(n, -Math.max(1200, latLen))), mul(norm(lat), Math.min(latLen, 700)));
        double dist = len(sub(aim, p));
        double speed = cone ? cruise : Math.min(cruise, Math.sqrt(2 * 25 * dist) + 60);
        double[] dir = norm(sub(aim, p));
        double[] vd = mul(dir, speed);
        double floorV = -(p[2] - 300) * 0.25;
        if (vd[2] < floorV) vd[2] = floorV;
        double[] a = mul(sub(vd, v), gain);
        a[2] += 20;
        if (a[2] < 1) a[2] = 1;
        double h = Math.hypot(a[0], a[1]);
        double tilt = Math.toRadians(59);
        if (h > a[2] * Math.tan(tilt)) { double k = a[2] * Math.tan(tilt) / h; a[0] *= k; a[1] *= k; }
        int throttle = clamp((int) Math.round(len(a) / 50 * 100), 0, 100);
        double psi = Math.atan2(f[1], f[0]);
        double want = Math.atan2(dir[1], dir[0]);
        double err = Math.atan2(Math.sin(psi - want), Math.cos(psi - want));
        int yaw = clamp((int) Math.round(err / Math.toRadians(30) * 100), -100, 100);
        double npsi = psi - yaw / 100.0 * Math.toRadians(30);
        double[] f0 = {Math.cos(npsi), Math.sin(npsi), 0}, r0 = {Math.sin(npsi), -Math.cos(npsi), 0};
        double[] t = norm(a);
        double ph = Math.asin(Math.max(-1, Math.min(1, dot(t, r0))));
        double th = Math.atan2(dot(t, f0), t[2]);
        int pitch = clamp((int) Math.round(Math.toDegrees(th) / 60 * 100), -100, 100);
        int roll = clamp((int) Math.round(Math.toDegrees(ph) / 60 * 100), -100, 100);
        return new int[]{throttle, yaw, pitch, roll};
    }

    static double[] nums(String line) {
        String[] t = line.trim().split(" ");
        double[] r = new double[t.length];
        for (int i = 0; i < t.length; i++) r[i] = Double.parseDouble(t[i]);
        return r;
    }

    static int clamp(int x, int lo, int hi) { return Math.max(lo, Math.min(hi, x)); }
    static double dot(double[] a, double[] b) { return a[0] * b[0] + a[1] * b[1] + a[2] * b[2]; }
    static double[] add(double[] a, double[] b) { return new double[]{a[0] + b[0], a[1] + b[1], a[2] + b[2]}; }
    static double[] sub(double[] a, double[] b) { return new double[]{a[0] - b[0], a[1] - b[1], a[2] - b[2]}; }
    static double[] mul(double[] a, double k) { return new double[]{a[0] * k, a[1] * k, a[2] * k}; }
    static double len(double[] a) { return Math.sqrt(dot(a, a)); }
    static double[] norm(double[] a) { double l = len(a); return l == 0 ? a : mul(a, 1 / l); }
}

final class Planner implements Bot {
    private final int horizon;
    private final double[][] params;
    private int me, laps;
    private Track track;
    private boolean first = true;
    private final Rules solo = new Rules(1, 1, Rules.NONE, 0, false, false, false);

    public Planner(int horizon, double[] cruises) {
        this.horizon = horizon;
        double[] gains = {0.3, 0.6}, leads = {0.3, 0.6};
        params = new double[cruises.length * 4][];
        int i = 0;
        for (double c : cruises) for (double g : gains) for (double l : leads) params[i++] = new double[]{c, g, l};
    }

    public Planner() { this(40, new double[]{300, 450, 600}); }

    public void init(List<String> lines) {
        String[] h = lines.get(0).split(" ");
        me = Integer.parseInt(h[1]);
        laps = Integer.parseInt(h[2]);
        int gates = Integer.parseInt(h[3]);
        Vec3[] c = new Vec3[gates], n = new Vec3[gates];
        for (int g = 0; g < gates; g++) {
            double[] t = Greedy.nums(lines.get(1 + g));
            c[g] = new Vec3(t[0], t[1], t[2]);
            n[g] = new Vec3(t[3], t[4], t[5]);
        }
        track = new Track(c, n);
    }

    public String turn(List<String> lines) {
        double[] s = Greedy.nums(lines.get(me));
        Drone base = new Drone(0, new Vec3(s[0], s[1], s[2]), new Vec3(s[6], s[7], s[8]));
        base.v = new Vec3(s[3], s[4], s[5]);
        base.u = new Vec3(s[9], s[10], s[11]);
        base.nextGate = (int) s[12];
        base.lap = (int) s[13];
        base.battery = (int) s[16];
        base.cutout = (int) s[17];
        base.mode = Command.ANGLE;
        double best = Double.NEGATIVE_INFINITY;
        int[] bestCmd = null;
        for (double[] pr : params) {
            Drone d = base.copy(0);
            Game g = new Game(solo, track, new Drone[]{d});
            int[] firstCmd = null;
            Command[] cmds = new Command[1];
            int t = 0;
            for (; t < horizon && d.active(); t++) {
                int[] k = Greedy.control(arr(d.p), arr(d.v), arr(d.f), arr(track.c[d.nextGate]), arr(track.n[d.nextGate]), pr[0], pr[1], pr[2]);
                if (firstCmd == null) firstCmd = k;
                cmds[0] = new Command(Command.ANGLE, k[0], k[1], k[2], k[3], false, "");
                g.step(cmds);
                if (d.lap >= laps) break;
            }
            double score = d.gatesCleared * 1e6 - g.distNext(d);
            if (d.state == Drone.DESTROYED) score -= 1e9;
            if (d.lap >= laps) score += 1e8 - t * 1e4;
            if (score > best) { best = score; bestCmd = firstCmd; }
        }
        String cmd = bestCmd[0] + " " + bestCmd[1] + " " + bestCmd[2] + " " + bestCmd[3];
        if (first) { first = false; return "ANGLE " + cmd; }
        return cmd;
    }

    private static double[] arr(Vec3 v) { return new double[]{v.x(), v.y(), v.z()}; }
}

final class PlannerX implements Bot {
    private static final double BOOST_VALUE = 1000, ITEM_VALUE = 600;
    private final int horizon = 40;
    private final double[][] params;
    private int me, laps, players;
    private Track track;
    private Vec3[] cellPos = new Vec3[0];
    private int[] cellType = new int[0];
    private boolean first = true;
    private final Rules solo = new Rules(1, 1, Rules.NONE, 9, false, true, false);

    public PlannerX() {
        double[] cruises = {300, 450, 600}, gains = {0.3, 0.6}, leads = {0.3, 0.6};
        params = new double[12][];
        int i = 0;
        for (double c : cruises) for (double g : gains) for (double l : leads) params[i++] = new double[]{c, g, l};
    }

    public void init(List<String> lines) {
        String[] h = lines.get(0).split(" ");
        players = Integer.parseInt(h[0]);
        me = Integer.parseInt(h[1]);
        laps = Integer.parseInt(h[2]);
        int gates = Integer.parseInt(h[3]);
        Vec3[] c = new Vec3[gates], n = new Vec3[gates];
        for (int g = 0; g < gates; g++) {
            double[] t = Greedy.nums(lines.get(1 + g));
            c[g] = new Vec3(t[0], t[1], t[2]);
            n[g] = new Vec3(t[3], t[4], t[5]);
        }
        track = new Track(c, n);
        int cells = Integer.parseInt(lines.get(1 + gates).trim());
        cellPos = new Vec3[cells];
        cellType = new int[cells];
        for (int k = 0; k < cells; k++) {
            String[] t = lines.get(2 + gates + k).trim().split(" ");
            cellPos[k] = new Vec3(Double.parseDouble(t[0]), Double.parseDouble(t[1]), Double.parseDouble(t[2]));
            cellType[k] = t[3].equals("CHARGE") ? Rules.CHARGE : t[3].equals("SHIELD") ? Rules.SHIELD : Rules.GHOST;
        }
    }

    public String turn(List<String> lines) {
        double[] s = Greedy.nums(lines.get(me));
        Drone base = new Drone(0, new Vec3(s[0], s[1], s[2]), new Vec3(s[6], s[7], s[8]));
        base.v = new Vec3(s[3], s[4], s[5]);
        base.u = new Vec3(s[9], s[10], s[11]);
        base.nextGate = (int) s[12];
        base.lap = (int) s[13];
        base.boosts = (int) s[14];
        base.boostTimer = (int) s[15];
        base.battery = (int) s[16];
        base.cutout = (int) s[17];
        base.item = (int) s[21];
        base.mode = Command.ANGLE;
        int[] timers = new int[cellPos.length];
        for (int k = 0; k < timers.length; k++) timers[k] = Integer.parseInt(lines.get(players + k).trim());

        List<double[]> cands = new ArrayList<>();
        for (double[] pr : params) {
            cands.add(new double[]{pr[0], pr[1], pr[2], 0, -1});
            if (base.boosts > 0) cands.add(new double[]{pr[0], pr[1], pr[2], 1, -1});
        }
        for (int k = 0; k < cellPos.length; k++) {
            if (timers[k] > 0 || (cellType[k] != Rules.CHARGE && base.item != 0)) continue;
            if (cellPos[k].sub(base.p).len() > 5000) continue;
            cands.add(new double[]{450, 0.6, 0.3, 0, k});
            cands.add(new double[]{600, 0.6, 0.3, 0, k});
        }
        double best = Double.NEGATIVE_INFINITY;
        int[] bestCmd = null;
        boolean bestBoost = false;
        for (double[] pr : cands) {
            Drone d = base.copy(0);
            Game g = new Game(solo, track, new Drone[]{d});
            g.cellPos = cellPos;
            g.cellType = cellType;
            g.cellTimer = timers.clone();
            int target = (int) pr[4];
            int[] firstCmd = null;
            Command[] cmds = new Command[1];
            int t = 0;
            for (; t < horizon && d.active(); t++) {
                boolean chase = target >= 0 && g.cellTimer[target] == 0 && t < 30;
                Vec3 c = chase ? cellPos[target] : track.c[d.nextGate];
                Vec3 n = chase ? cellPos[target].sub(d.p).norm() : track.n[d.nextGate];
                int[] k = Greedy.control(arr(d.p), arr(d.v), arr(d.f), arr(c), arr(n), pr[0], pr[1], pr[2]);
                if (firstCmd == null) firstCmd = k;
                cmds[0] = new Command(Command.ANGLE, k[0], k[1], k[2], k[3], t == 0 && pr[3] == 1, "");
                g.step(cmds);
                if (d.lap >= laps) break;
            }
            double score = d.gatesCleared * 1e6 - g.distNext(d) + d.boosts * BOOST_VALUE + (d.item != 0 ? ITEM_VALUE : 0)
                    + (d.shield > 0 || d.ghost > 0 ? ITEM_VALUE : 0);
            if (d.state == Drone.DESTROYED) score -= 1e9;
            if (d.lap >= laps) score += 1e8 - t * 1e4;
            if (score > best) { best = score; bestCmd = firstCmd; bestBoost = pr[3] == 1; }
        }
        boolean use = base.item != 0 && threatened(lines, base);
        String cmd = bestCmd[0] + " " + bestCmd[1] + " " + bestCmd[2] + " " + bestCmd[3] + (bestBoost ? " BOOST" : "") + (use ? " USE" : "");
        if (first) { first = false; return "ANGLE " + cmd; }
        return cmd;
    }

    private boolean threatened(List<String> lines, Drone me0) {
        for (int j = 0; j < players; j++) {
            if (j == me) continue;
            double[] o = Greedy.nums(lines.get(j));
            if (o[18] != 1) continue;
            Vec3 op = new Vec3(o[0], o[1], o[2]), ov = new Vec3(o[3], o[4], o[5]);
            Vec3 rel = op.sub(me0.p);
            double closing = -rel.dot(ov.sub(me0.v)) / Math.max(1, rel.len());
            if (rel.len() < 1500 && closing > Rules.CUTOUT_SPEED * 0.6) return true;
        }
        return false;
    }

    private static double[] arr(Vec3 v) { return new double[]{v.x(), v.y(), v.z()}; }
}

final class AcroControl {
    private static final double RATE = Math.toRadians(60);

    public static int[] control(Vec3 p, Vec3 v, Vec3 f0, Vec3 u0, Vec3 c, Vec3 n, double cruise, double gain, double lead, double tiltDeg) {
        Vec3 f = f0.norm();
        Vec3 u = u0.sub(f.mul(u0.dot(f))).norm();
        double along = p.sub(c).dot(n);
        Vec3 lat = p.sub(c).sub(n.mul(along));
        double latLen = lat.len();
        boolean cone = along < 0 && latLen < -along * 1.2 + 300;
        Vec3 aim = cone ? c.add(n.mul(along * lead + 200))
                : c.add(n.mul(-Math.max(1200, latLen))).add(lat.norm().mul(Math.min(latLen, 700)));
        double dist = aim.sub(p).len();
        double speed = cone ? cruise : Math.min(cruise, Math.sqrt(2 * 30 * dist) + 60);
        Vec3 dir = aim.sub(p).norm();
        Vec3 vd = dir.mul(speed);
        double floorV = -(p.z() - 350) * 0.25;
        if (vd.z() < floorV) vd = new Vec3(vd.x(), vd.y(), floorV);
        Vec3 a = vd.sub(v).mul(gain);
        double az = Math.max(1, a.z() + 20);
        double h = Math.hypot(a.x(), a.y());
        double limit = az * Math.tan(Math.toRadians(tiltDeg));
        double ax = a.x(), ay = a.y();
        if (h > limit) { ax *= limit / h; ay *= limit / h; }
        Vec3 acc = new Vec3(ax, ay, az);
        Vec3 ut = acc.norm();
        Vec3 heading = new Vec3(dir.x(), dir.y(), 0);
        if (heading.len() < 1e-6) heading = new Vec3(f.x(), f.y(), 0);
        Vec3 ft = heading.sub(ut.mul(heading.dot(ut)));
        if (ft.len() < 1e-6) ft = f.sub(ut.mul(f.dot(ut)));
        ft = ft.norm();
        Vec3 w = rotation(f, u, ft, ut);
        Vec3 r = f.cross(u);
        int pitch = clamp((int) Math.round(-w.dot(r) / RATE * 100));
        int roll = clamp((int) Math.round(w.dot(f) / RATE * 100));
        int yaw = clamp((int) Math.round(-w.dot(u) / RATE * 100));
        double tiltErr = Math.acos(Math.max(-1, Math.min(1, u.dot(ut))));
        double thrust = acc.len() * Math.max(0, Math.cos(tiltErr));
        int throttle = Math.max(0, Math.min(100, (int) Math.round(thrust / 50 * 100)));
        return new int[]{throttle, yaw, pitch, roll};
    }

    private static int clamp(int x) { return Math.max(-100, Math.min(100, x)); }

    static Vec3 rotation(Vec3 f, Vec3 u, Vec3 ft, Vec3 ut) {
        double[] qc = quat(f, u), qt = quat(ft, ut);
        double w = qt[0] * qc[0] + qt[1] * qc[1] + qt[2] * qc[2] + qt[3] * qc[3];
        double x = -qt[0] * qc[1] + qt[1] * qc[0] - qt[2] * qc[3] + qt[3] * qc[2];
        double y = -qt[0] * qc[2] + qt[1] * qc[3] + qt[2] * qc[0] - qt[3] * qc[1];
        double z = -qt[0] * qc[3] - qt[1] * qc[2] + qt[2] * qc[1] + qt[3] * qc[0];
        if (w < 0) { w = -w; x = -x; y = -y; z = -z; }
        double s = Math.sqrt(x * x + y * y + z * z);
        if (s == 0) return Vec3.ZERO;
        double angle = 2 * Math.atan2(s, w);
        return new Vec3(x, y, z).mul(angle / s);
    }

    static double[] quat(Vec3 f, Vec3 u) {
        Vec3 l = u.cross(f);
        double m00 = f.x(), m01 = l.x(), m02 = u.x(), m10 = f.y(), m11 = l.y(), m12 = u.y(), m20 = f.z(), m21 = l.z(), m22 = u.z();
        double tr = m00 + m11 + m22, s;
        if (tr > 0) {
            s = Math.sqrt(tr + 1) * 2;
            return new double[]{s / 4, (m21 - m12) / s, (m02 - m20) / s, (m10 - m01) / s};
        } else if (m00 > m11 && m00 > m22) {
            s = Math.sqrt(1 + m00 - m11 - m22) * 2;
            return new double[]{(m21 - m12) / s, s / 4, (m01 + m10) / s, (m02 + m20) / s};
        } else if (m11 > m22) {
            s = Math.sqrt(1 + m11 - m00 - m22) * 2;
            return new double[]{(m02 - m20) / s, (m01 + m10) / s, s / 4, (m12 + m21) / s};
        } else {
            s = Math.sqrt(1 + m22 - m00 - m11) * 2;
            return new double[]{(m10 - m01) / s, (m02 + m20) / s, (m12 + m21) / s, s / 4};
        }
    }
}

final class AcroPlanner implements Bot {
    private static final double BOOST_VALUE = 1000, ITEM_VALUE = 600;
    private final int horizon;
    private final double[][] params;
    private int me, laps, players;
    private Track track;
    private Vec3[] cellPos = new Vec3[0];
    private int[] cellType = new int[0];
    private boolean first = true;
    private final Rules solo = new Rules(3, 1, Rules.NONE, 9, true, true, false);
    private double[] lastPick;

    public AcroPlanner(int horizon) {
        this.horizon = horizon;
        double[] cruises = {450, 650, 850}, tilts = {60, 72, 80}, leads = {0.3, 0.6};
        params = new double[cruises.length * tilts.length * leads.length][];
        int i = 0;
        for (double c : cruises) for (double t : tilts) for (double l : leads) params[i++] = new double[]{c, 0.4, l, t};
    }

    public AcroPlanner() { this(40); }

    public void init(List<String> lines) {
        String[] h = lines.get(0).split(" ");
        players = Integer.parseInt(h[0]);
        me = Integer.parseInt(h[1]);
        laps = Integer.parseInt(h[2]);
        int gates = Integer.parseInt(h[3]);
        Vec3[] c = new Vec3[gates], n = new Vec3[gates];
        for (int g = 0; g < gates; g++) {
            double[] t = Greedy.nums(lines.get(1 + g));
            c[g] = new Vec3(t[0], t[1], t[2]);
            n[g] = new Vec3(t[3], t[4], t[5]);
        }
        track = new Track(c, n);
        int cells = Integer.parseInt(lines.get(1 + gates).trim());
        cellPos = new Vec3[cells];
        cellType = new int[cells];
        for (int k = 0; k < cells; k++) {
            String[] t = lines.get(2 + gates + k).trim().split(" ");
            cellPos[k] = new Vec3(Double.parseDouble(t[0]), Double.parseDouble(t[1]), Double.parseDouble(t[2]));
            cellType[k] = t[3].equals("CHARGE") ? Rules.CHARGE : t[3].equals("SHIELD") ? Rules.SHIELD : Rules.GHOST;
        }
    }

    public String turn(List<String> lines) {
        double[] s = Greedy.nums(lines.get(me));
        Drone base = new Drone(0, new Vec3(s[0], s[1], s[2]), new Vec3(s[6], s[7], s[8]));
        base.v = new Vec3(s[3], s[4], s[5]);
        base.u = new Vec3(s[9], s[10], s[11]);
        base.nextGate = (int) s[12];
        base.lap = (int) s[13];
        base.boosts = (int) s[14];
        base.boostTimer = (int) s[15];
        base.battery = (int) s[16];
        base.cutout = (int) s[17];
        base.item = (int) s[21];
        base.mode = Command.ACRO;
        int[] timers = new int[cellPos.length];
        for (int k = 0; k < timers.length; k++) timers[k] = Integer.parseInt(lines.get(players + k).trim());

        List<double[]> cands = new ArrayList<>();
        for (double[] pr : params) {
            cands.add(new double[]{pr[0], pr[1], pr[2], pr[3], 0, -1});
            if (base.boosts > 0) cands.add(new double[]{pr[0], pr[1], pr[2], pr[3], 1, -1});
        }
        for (int k = 0; k < cellPos.length; k++) {
            if (timers[k] > 0 || (cellType[k] != Rules.CHARGE && base.item != 0)) continue;
            if (cellPos[k].sub(base.p).len() > 5000) continue;
            cands.add(new double[]{650, 0.5, 0.3, 72, 0, k});
            cands.add(new double[]{850, 0.5, 0.3, 80, 0, k});
        }
        double best = Double.NEGATIVE_INFINITY;
        int[] bestCmd = null;
        boolean bestBoost = false;
        double[] bestPr = null;
        for (double[] pr : cands) {
            double score = rollout(base, timers, pr);
            if (lastPick != null && same(pr, lastPick)) score += 150;
            if (score > best) {
                best = score;
                bestPr = pr;
                bestBoost = pr[4] == 1;
            }
        }
        lastPick = bestPr;
        bestCmd = firstCommand(base, bestPr);
        boolean use = base.item != 0 && threatened(lines, base);
        String cmd = bestCmd[0] + " " + bestCmd[1] + " " + bestCmd[2] + " " + bestCmd[3] + (bestBoost ? " BOOST" : "") + (use ? " USE" : "");
        if (first) { first = false; return "ACRO " + cmd; }
        return cmd;
    }

    private static boolean same(double[] a, double[] b) {
        for (int i = 0; i < 4; i++) if (a[i] != b[i]) return false;
        return a[5] == b[5];
    }

    private int[] firstCommand(Drone d, double[] pr) {
        Vec3[] cn = target(d, pr, cellTimersZero());
        return AcroControl.control(d.p, d.v, d.f, d.u, cn[0], cn[1], pr[0], pr[1], pr[2], pr[3]);
    }

    private int[] cellTimersZero() { return new int[cellPos.length]; }

    private Vec3[] target(Drone d, double[] pr, int[] timers) {
        int k = (int) pr[5];
        if (k >= 0 && timers[k] == 0) return new Vec3[]{cellPos[k], cellPos[k].sub(d.p).norm()};
        return new Vec3[]{track.c[d.nextGate], track.n[d.nextGate]};
    }

    private double rollout(Drone base, int[] timers, double[] pr) {
        Drone d = base.copy(0);
        Game g = new Game(solo, track, new Drone[]{d});
        g.cellPos = cellPos;
        g.cellType = cellType;
        g.cellTimer = timers.clone();
        Command[] cmds = new Command[1];
        int t = 0;
        for (; t < horizon && d.active(); t++) {
            boolean chase = pr[5] >= 0 && t < 30;
            Vec3[] cn = chase ? target(d, pr, g.cellTimer) : new Vec3[]{track.c[d.nextGate], track.n[d.nextGate]};
            int[] k = AcroControl.control(d.p, d.v, d.f, d.u, cn[0], cn[1], pr[0], pr[1], pr[2], pr[3]);
            cmds[0] = new Command(Command.ACRO, k[0], k[1], k[2], k[3], t == 0 && pr[4] == 1, "");
            g.step(cmds);
            if (d.lap >= laps) break;
        }
        double score = d.gatesCleared * 1e6 - g.distNext(d) + d.boosts * BOOST_VALUE + (d.item != 0 ? ITEM_VALUE : 0)
                + (d.shield > 0 || d.ghost > 0 ? ITEM_VALUE : 0);
        if (d.state == Drone.DESTROYED) score -= 1e9;
        if (d.lap >= laps) score += 1e8 - t * 1e4;
        return score;
    }

    private boolean threatened(List<String> lines, Drone me0) {
        for (int j = 0; j < players; j++) {
            if (j == me) continue;
            double[] o = Greedy.nums(lines.get(j));
            if (o[18] != 1) continue;
            Vec3 op = new Vec3(o[0], o[1], o[2]), ov = new Vec3(o[3], o[4], o[5]);
            Vec3 rel = op.sub(me0.p);
            double closing = -rel.dot(ov.sub(me0.v)) / Math.max(1, rel.len());
            if (rel.len() < 1500 && closing > Rules.CUTOUT_SPEED * 0.6) return true;
        }
        return false;
    }
}

